import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int mod = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] v = new int[10];
        for (int i = 0; i < k; i++) {
            v[in.nextInt()] = 1;
        }

        int[] ans = {1};
        int p = n / 2;
        while (true) {
            if ((p & 1) == 1) {
                ans = multiplyPolynomials(ans, v, mod);
            }
            p >>= 1;
            if (p == 0) break;
            v = multiplyPolynomials(v, v, mod);
        }

        long res = 0;
        for (int x : ans) {
            res = (res + (long)x * x) % mod;
        }
        out.println(res);
        out.close();
    }

    int[] multiplyPolynomials(int[] a, int[] b, int mod) {
        int need = a.length + b.length - 1;
        int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);

        double[] aReal = new double[n];
        double[] aImag = new double[n];
        for (int i = 0; i < a.length; i++) {
            int x = ((a[i] % mod) + mod) % mod;
            aReal[i] = x & 0x7FFF;
            aImag[i] = x >>> 15;
        }
        performFFT(aReal, aImag, false);

        double[] bReal = new double[n];
        double[] bImag = new double[n];
        for (int i = 0; i < b.length; i++) {
            int x = ((b[i] % mod) + mod) % mod;
            bReal[i] = x & 0x7FFF;
            bImag[i] = x >>> 15;
        }
        performFFT(bReal, bImag, false);

        double[] resReal = new double[n];
        double[] resImag = new double[n];
        double[] tmpReal = new double[n];
        double[] tmpImag = new double[n];

        double factor = 0.25 / n;
        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);

            double ar1 = (aReal[i] + aReal[j]) * 0.5;
            double ai1 = (aImag[i] - aImag[j]) * 0.5;
            double ar2 = (aImag[i] + aImag[j]) * 0.5;
            double ai2 = (aReal[j] - aReal[i]) * 0.5;

            double br1 = (bReal[i] + bReal[j]) * 0.5;
            double bi1 = (bImag[i] - bImag[j]) * 0.5;
            double br2 = (bImag[i] + bImag[j]) * 0.5;
            double bi2 = (bReal[j] - bReal[i]) * 0.5;

            resReal[i] = ar1 * br1 - ai1 * bi1 - ar2 * bi2 - ai2 * br2;
            resImag[i] = ar1 * bi1 + ai1 * br1 + ar2 * br2 - ai2 * bi2;
            tmpReal[i] = ar1 * br2 - ai1 * bi2 + ar2 * br1 - ai2 * bi1;
            tmpImag[i] = ar1 * bi2 + ai1 * br2 + ar2 * bi1 + ai2 * br1;
        }

        performFFT(resReal, resImag, true);
        performFFT(tmpReal, tmpImag, true);

        int[] result = new int[need];
        for (int i = 0; i < need; i++) {
            long part1 = Math.round(resReal[i]);
            long part2 = Math.round(tmpReal[i]);
            long part3 = Math.round(resImag[i]);
            result[i] = (int)((part1 + (part2 % mod << 15) + (part3 % mod << 30)) % mod);
        }
        return result;
    }

    void performFFT(double[] real, double[] imag, boolean inverse) {
        int n = real.length;
        int bits = 31 - Integer.numberOfLeadingZeros(n);
        for (int i = 1; i < n; i++) {
            int j = Integer.reverse(i) >>> (32 - bits);
            if (i < j) {
                double t = real[i]; real[i] = real[j]; real[j] = t;
                t = imag[i]; imag[i] = imag[j]; imag[j] = t;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cosTable = new double[half];
            double[] sinTable = new double[half];
            double angle = 2 * Math.PI / len * (inverse ? -1 : 1);
            for (int i = 0; i < half; i++) {
                cosTable[i] = Math.cos(i * angle);
                sinTable[i] = Math.sin(i * angle);
            }

            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; j++) {
                    double cr = cosTable[j];
                    double ci = sinTable[j];
                    double ur = real[i + j];
                    double ui = imag[i + j];
                    double vr = real[i + j + half] * cr - imag[i + j + half] * ci;
                    double vi = real[i + j + half] * ci + imag[i + j + half] * cr;

                    real[i + j] = ur + vr;
                    imag[i + j] = ui + vi;
                    real[i + j + half] = ur - vr;
                    imag[i + j + half] = ui - vi;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                real[i] /= n;
                imag[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr, len;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (len == -1) throw new RuntimeException();
            if (ptr >= len) {
                ptr = 0;
                try { len = stream.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c;
            while ((c = read()) <= ' ') if (c == -1) throw new RuntimeException();
            int sign = 1;
            if (c == '-') { sign = -1; c = read(); }
            int val = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                val = val * 10 + c - '0';
                c = read();
            } while (c > ' ');
            return val * sign;
        }
    }
}
